        for job in self.jobs.values():
            self.assertEqual(job["runs-on"], "ubuntu-latest")

    def test_steps_use_checkout_v4(self):
        for name, job in self.jobs.items():
            uses = [s.get("uses", "") for s in job["steps"]]
            self.assertIn(
